#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
typedef long double ld;
typedef pair<int,int> pii;
typedef pair<ll,ll> pll;
typedef pair<ld,ld> pdd;
typedef complex<ld> pt;
typedef vector<pt> pol;
typedef vector<int> vi;

const char nl = '\n';
const ll INF = 0x3f3f3f3f;
const ll INFLL = 0x3f3f3f3f3f3f3f3f;
const ll MOD = 1000000007LL;
const ld EPS = 1e-10;
mt19937_64 rng(chrono::steady_clock::now().time_since_epoch().count());

const int T = 99;
const int C = 12;

struct FlowEdge {
    int to, rev;
    ll flow, cap, cost;
};

FlowEdge edges[5000][5000];
int edgeCount[5000];
ll totalMinCost;

void initFlow(int n) {
    totalMinCost = 0;
    for (int i = 0; i < n; ++i) {
        edgeCount[i] = 0;
    }
}

void addFlowEdge(int u, int v, ll cap = 1, ll cost = 0) {
    totalMinCost = max(totalMinCost, cap);
    edges[u][edgeCount[u]++] = {v, edgeCount[v], 0, cap, cost};
    edges[v][edgeCount[v]++] = {u, edgeCount[u] - 1, 0, 0, -cost};
}

bool visited[5000];
int prevEdge[5000];
ll potential[5000], dist[5000];

void setupPotential(int n) {
    fill(potential, potential + n, 0);
    for (int iter = 1; iter < n; ++iter) {
        for (int node = 0; node < n; ++node) {
            for (int idx = 0; idx < edgeCount[node]; ++idx) {
                FlowEdge& e = edges[node][idx];
                if (e.cap) {
                    potential[e.to] = min(potential[e.to], potential[node] + e.cost);
                }
            }
        }
    }
}

ll findAugmentingPath(int src, int dst, ll& totalCost, int nodeCount, bool useBFS) {
    fill(visited, visited + nodeCount, false);
    fill(dist, dist + nodeCount, INF);
    dist[src] = 0;

    if (useBFS) {
        queue<int> q;
        q.push(src);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            if (visited[u]) continue;
            visited[u] = true;
            for (int idx = 0; idx < edgeCount[u]; ++idx) {
                FlowEdge& e = edges[u][idx];
                if (e.flow < e.cap && dist[e.to] > dist[u] + potential[u] - potential[e.to] + e.cost) {
                    dist[e.to] = dist[u] + potential[u] - potential[e.to] + e.cost;
                    prevEdge[e.to] = idx;
                    q.push(e.to);
                }
            }
        }
    } else {
        for (int u = src; u != -1; ) {
            visited[u] = true;
            for (int idx = 0; idx < edgeCount[u]; ++idx) {
                FlowEdge& e = edges[u][idx];
                if (e.flow < e.cap && dist[e.to] > dist[u] + potential[u] - potential[e.to] + e.cost) {
                    dist[e.to] = dist[u] + potential[u] - potential[e.to] + e.cost;
                    prevEdge[e.to] = idx;
                }
            }
            u = -1;
            ll best = INF;
            for (int i = 0; i < nodeCount; ++i) {
                if (!visited[i] && dist[i] < best) {
                    best = dist[u = i];
                }
            }
        }
    }

    if (dist[dst] >= INF) return 0;

    ll bottleneck = INF;
    for (int node = dst; node != src; ) {
        int idx = prevEdge[node];
        FlowEdge& revEdge = edges[node][idx];
        bottleneck = min(bottleneck, edges[revEdge.to][revEdge.rev].cap - edges[revEdge.to][revEdge.rev].flow);
        node = revEdge.to;
    }

    for (int node = dst; node != src; ) {
        int idx = prevEdge[node];
        FlowEdge& revEdge = edges[node][idx];
        FlowEdge& forwardEdge = edges[revEdge.to][revEdge.rev];
        forwardEdge.flow += bottleneck;
        revEdge.flow -= bottleneck;
        totalCost += bottleneck * forwardEdge.cost;
        node = revEdge.to;
    }

    for (int i = 0; i < nodeCount; ++i) {
        potential[i] = min(INF, dist[i] + potential[i]);
    }
    return bottleneck;
}

ll minCostMaxFlow(int src, int dst, ll& totalCost, int nodeCount, bool useBFS) {
    setupPotential(nodeCount);
    ll totalFlow = 0;
    totalCost = 0;
    while (ll df = findAugmentingPath(src, dst, totalCost, nodeCount, useBFS)) {
        totalFlow += df;
    }
    return totalFlow;
}

int main() {
    ios::sync_with_stdio(0);
    cin.tie(0); cout.tie(0);
    cout << fixed << setprecision(10);

    int n,m,k,c,d;
    cin>>n>>m>>k>>c>>d;

    const int source = 0;
    const int sink = n*T+1;

    initFlow(sink+1);

    for(int i=0;i<k;i++) {
        int a;
        cin>>a;
        addFlowEdge(source, a, 1, 0);
    }
    for(int t=0;t<T;t++) {
        addFlowEdge(1+t*n, sink, INF, 0);
        if(t>0) {
            for(int i=1;i<=n;i++) {
                addFlowEdge(i+(t-1)*n, i+t*n, INF, c);
            }
        }
    }

    for(int i=0;i<m;i++) {
        int a, b;
        cin >> a >> b;
        for(int j=0;j<C;j++) {
            int cost = (j+1)*(j+1) - j*j;
            for(int t=1;t<T;t++) {
                addFlowEdge(a+(t-1)*n, b+t*n, 1, cost*d + c);
                addFlowEdge(b+(t-1)*n, a+t*n, 1, cost*d + c);
            }
        }
    }

    ll price, flow = minCostMaxFlow(source, sink, price, sink+1, true);
    assert(flow==k);
    cout << price << nl;

    return 0;
}
